def add_loadsave_hooks(text, unit):
    rows = PATCHES.get(unit, ())
    if not rows: return text
    if 'NFS_PRIVATE_LOADSAVE_LIVE_BEGIN:' in text:
        raise ValueError('Load/Save hooks already present: ' + unit)
    edits = []
    for context, prefix, original, replacement in rows:
        if text.count(context) != 1:
            raise ValueError('Load/Save source anchor mismatch: ' + unit)
        start = text.index(context) + prefix
        if text[start:start+len(original)] != original:
            raise ValueError('Load/Save original call changed: ' + unit)
        edits.append((start, start+len(original), replacement))
    edits.sort(reverse=True)
    previous = len(text)+1
    for start, end, replacement in edits:
        if end > previous: raise ValueError('Overlapping Load/Save scopes: ' + unit)
        text = text[:start] + replacement + text[end:]
        previous = start
    return text
